<main class="py-5"><div class="container"><h1 class="h2 text-primary mb-4">Gestion des employés</h1>
<section class="card border-0 shadow-sm mb-4"><div class="card-body"><h2 class="h5">Créer un employé</h2><p class="small text-muted">Le mot de passe est défini par l'administrateur mais n'est pas communiqué dans l'email de notification.</p><form method="post" action="/admin/employees" class="row g-3"><input type="hidden" name="csrf_token" value="<?= $escape($csrfToken) ?>"><?php foreach(['first_name'=>'Prénom','last_name'=>'Nom','email'=>'Email','phone'=>'Téléphone','gsm'=>'GSM','address'=>'Adresse'] as $f=>$label): ?><div class="<?= $f==='address'?'col-12':'col-md-6' ?>"><label class="form-label"><?= $label ?></label><?php if($f==='address'): ?><textarea class="form-control" name="<?= $f ?>" required></textarea><?php else: ?><input class="form-control" name="<?= $f ?>" type="<?= $f==='email'?'email':'text' ?>" required><?php endif; ?></div><?php endforeach; ?><div class="col-12"><button class="btn btn-primary">Créer l'employé</button></div></form></div></section>
<?php foreach($employees as $employee): ?><section class="card border-0 shadow-sm mb-3"><div class="card-body d-flex justify-content-between align-items-center"><div><strong><?= $escape($employee['first_name'].' '.$employee['last_name']) ?></strong><div class="small text-muted"><?= $escape($employee['email']) ?> — <?= $employee['role'] === 'admin' ? 'Administrateur' : 'Employé' ?></div></div><?php if($employee['role']==='employee'): ?><?php if($employee['is_active']): ?><form method="post" action="/admin/employees/<?= $employee['id'] ?>/disable"><input type="hidden" name="csrf_token" value="<?= $escape($csrfToken) ?>"><button class="btn btn-outline-danger btn-sm">Désactiver</button></form><?php else: ?><form method="post" action="/admin/employees/<?= $employee['id'] ?>/enable"><input type="hidden" name="csrf_token" value="<?= $escape($csrfToken) ?>"><button class="btn btn-outline-success btn-sm">Réactiver</button></form><?php endif; ?><?php endif; ?></div></section><?php endforeach; ?>
</div></main>
